<script setup>
import { useForm } from '@inertiajs/vue3'; import AdminLayout from '../../Layouts/AdminLayout.vue';
const props=defineProps({settings:Object}); const form=useForm({settings:{...props.settings}}); const ensure=(key)=>{if(form.settings[key]===undefined)form.settings[key]=''}; ['facebook_url','instagram_url','email','seo_default_title','seo_default_description'].forEach(ensure); const submit=()=>form.put('/admin/settings');
</script>
<template><AdminLayout><p class="text-xs uppercase tracking-widest text-[#c56b4d]">সাইট কনফিগারেশন</p><h1 class="mt-2 font-serif text-4xl">সেটিংস</h1><form @submit.prevent="submit" class="mt-8 max-w-2xl space-y-5 rounded-2xl bg-white p-7"><label>ইমেইল<input v-model="form.settings.email" type="email" class="field" /></label><label>Facebook URL<input v-model="form.settings.facebook_url" type="url" class="field" /></label><label>Instagram URL<input v-model="form.settings.instagram_url" type="url" class="field" /></label><label>SEO title<input v-model="form.settings.seo_default_title" class="field" /></label><label>SEO description<textarea v-model="form.settings.seo_default_description" rows="4" class="field" /></label><button class="rounded-full bg-[#1d4843] px-6 py-3 font-semibold text-white">সেটিংস সংরক্ষণ করুন</button></form></AdminLayout></template><style scoped>.field{display:block;margin-top:.5rem;width:100%;border:0;border-radius:.5rem;background:#f7f5f0;padding:.75rem 1rem;box-shadow:inset 0 0 0 1px #dfe1d8;outline:none}label{display:block;font-size:.875rem;color:#49605c}</style>
